  import { pinErrors } from './pinning';
  import { tooltip } from './tooltip';
  import { liveNumber } from './liveNumber';
  import type { Pose } from './types';
  let {pose,baseline=null,floorHeight=0,selectorStyle='buttons',selectedBone=figureKey,tool=$bindable('select'),space=$bindable('local'),snap=$bindable(false),axis=$bindable('all'),handles=$bindable(true),ghostPartners=$bindable(true),jointGroup=$bindable('body'),linked=$bindable(false),group=false,busy=false,canUndo=false,canRedo=false,canDraft=false,canNew=false,onNew=()=>{},onEditing=()=>{},onSelect,onFocus,onPosition,onRotation,onFacing,onFloorOffset,onUndo,onRedo,onReset,onZero,onPin,onUnpinAll,onReach,onSave,onLoad}: {pose:Pose|null;baseline?:Pose|null;floorHeight?:number;selectorStyle?:'buttons'|'map';selectedBone?:string;tool?:EditTool;space?:'local'|'world';snap?:boolean;axis?:EditAxis;handles?:boolean;ghostPartners?:boolean;jointGroup?:JointGroup;linked?:boolean;group?:boolean;busy?:boolean;canUndo?:boolean;canRedo?:boolean;canDraft?:boolean;canNew?:boolean;onNew?:()=>void;onEditing?:(active:boolean)=>void;onSelect:(bone:string)=>void;onFocus:()=>void;onPosition:(values:number[])=>void;onRotation:(values:number[])=>void;onFacing:(value:FacingPreset)=>void;onFloorOffset:(value:number)=>void;onUndo:()=>void;onRedo:()=>void;onReset:(all:boolean)=>void;onZero:(withChildren:boolean)=>void;onPin:(component:'position'|'rotation')=>void;onUnpinAll:()=>void;onReach:(target:number[])=>void;onSave:()=>void;onLoad:()=>void}=$props();
  let open=$state(true),chooserOpen=$state(true),search=$state(''),target=$state([0,0,0]),targetKey='',selectionKey='',lastTool=tool;let body=$state<HTMLDivElement>();
  $effect(()=>{if(tool!==lastTool){if(tool==='select')chooserOpen=true;lastTool=tool;}});
  $effect(()=>{const key=String(pose?.personId);if(key!==selectionKey){selectionKey=key;void tick().then(()=>body?.scrollTo({top:0}));}});
  const node=$derived(pose?.rig.nodes.find(n=>selectedBone===figureKey?!n.parent:n.id===selectedBone));
  const angles=$derived(pose&&node?(selectedBone===figureKey?pose.rootRotation??[0,0,0]:evaluatedChannels(pose.rig,pose.rotations)[node.id]??[0,0,0]):[0,0,0]);
  let searchGroup=$state<JointFilter>('all');
  const searchGroups=$derived(pose?jointSearchGroups(pose,search,searchGroup):[]);
  const searchCount=$derived(searchGroups.reduce((count,group)=>count+group.nodes.length,0));
  const canZeroSelected=$derived(!!pose&&zeroSelection(pose,selectedBone)!==pose);
  const canZeroChildren=$derived(!!pose&&zeroSelection(pose,selectedBone,true)!==pose);
  const selectedPin=$derived(pose?.pins?.[selectedBone]);
  const pinStatus=$derived(pose?pinErrors(pose):[]);
  const canPin=$derived(!!node&&node.type==='bone'&&selectedBone!==figureKey);
  const reachJoint=$derived(isReachJoint(selectedBone)),canMove=$derived((selectedBone===figureKey||reachJoint)&&!selectedPin?.position);
  let handSide=$state('l'),lastHandSelection='';
  $effect(()=>{const key=String(pose?.personId)+'/'+selectedBone;if(key!==lastHandSelection){lastHandSelection=key;if(pose){const section=jointSection(pose,selectedBone);if(section.endsWith('-hand'))handSide=section[0];}}});
