  function currentTarget(){if(!pose||!node)return;target=forwardKinematics(pose.rig,previewRotations(pose),pose.translation).get(node.id)!.position.toArray();}
  $effect(()=>{const key=pose?.personId+'/'+selectedBone;if(key!==targetKey){targetKey=key;currentTarget();}});
  function positionAxis(axis:number,value:number){if(!pose||busy||!Number.isFinite(value))return;const values=[...pose.translation];values[axis]=value;onPosition(values);}
  function rotationAxis(axis:number,value:number){if(!pose||busy||!Number.isFinite(value))return;const values=[...angles];values[axis]=value;onRotation(values);}

</script>
<div class="editor-inspector" class:collapsed={!open}>
  <div class="editor-heading"><button class="text-button" aria-label={open?'Collapse Pose controls':'Expand Pose controls'} aria-expanded={open} use:tooltip={'Show or collapse pose editing controls.'} onclick={()=>open=!open}><SlidersHorizontal size={15}/> Pose controls <ChevronDown size={13}/></button>{#if open}<span class="editor-history"><button class="icon-button" aria-label="Undo pose edit" aria-disabled={!canUndo||busy} use:tooltip={canUndo?'Undo the last pose edit · Ctrl+Z':'No pose edits to undo.'} onclick={()=>{if(canUndo&&!busy)onUndo();}}><Undo2 size={15}/></button><button class="icon-button" aria-label="Redo pose edit" aria-disabled={!canRedo||busy} use:tooltip={canRedo?'Redo the pose edit · Ctrl+Shift+Z':'No pose edits to redo.'} onclick={()=>{if(canRedo&&!busy)onRedo();}}><Redo2 size={15}/></button></span>{/if}</div>
  {#if open}<div class="editor-body" bind:this={body}>
    {#if !pose}<div class="editor-empty"><Crosshair size={24}/><h3>Make a pose your own.</h3><p>Start a neutral pose, extract a person, or arrange an interaction. Then refine the joints here.</p><button class="primary wide" disabled={busy||!canNew} onclick={onNew} use:tooltip={'Start a neutral pose using the selected generation’s cached rig. No photo or neural extraction is needed.'}><Plus size={14}/> New pose</button><button class="secondary wide" disabled={busy||!canDraft} onclick={onLoad} use:tooltip={canDraft?"Restore a previously saved editor draft for this reference.":"Open a reference or saved pose in History to restore its draft."}><FolderOpen size={14}/> Restore local draft</button></div>{:else}
      <div class="selected-joint-card"><div><small>MANNEQUIN {pose.personId} · SELECTED</small><strong>{selectedBone===figureKey?'Whole figure':node?jointLabel(node):'Choose a joint'}</strong></div><button class="icon-button" aria-label={selectedBone===figureKey?'Focus selected mannequin':'Focus selected joint'} aria-disabled={busy} use:tooltip={selectedBone===figureKey?'Frame this mannequin closely. Fit mannequin in view restores the whole studio.':'Zoom to this joint. Fit mannequin in view restores the whole studio.'} onclick={()=>{if(!busy)onFocus();}}><Crosshair size={16}/></button></div>
      <div class="editor-tool-row"><button class="compact-button" class:active={tool==='select'} aria-pressed={tool==='select'} disabled={busy} use:tooltip={'Choose joints without a gizmo getting in the way · Q.'} onclick={()=>tool='select'}><MousePointer2 size={13}/> Select</button><button class="compact-button" class:active={tool==='translate'} aria-pressed={tool==='translate'} aria-disabled={!canMove||busy} use:tooltip={selectedPin?.position?'Unpin Position to move this joint.':canMove?'Move this figure, hand or foot with the arrows · W. Limb movement changes parent rotations while preserving bone lengths.':'Move supports Whole figure, hands and feet. This joint uses rotation to preserve the rig.'} onclick={()=>{if(canMove&&!busy)tool='translate';}}><Move size={13}/> Move</button><button class="compact-button" class:active={tool==='rotate'} aria-pressed={tool==='rotate'} disabled={busy||!!selectedPin?.rotation} use:tooltip={selectedPin?.rotation?'Unpin Rotation to rotate this joint.':'Rotate the selected figure or joint · E. Values use DAZ rotation channels.'} onclick={()=>tool='rotate'}><Rotate3D size={13}/> Rotate</button></div>
      <div class="axis-isolation" aria-label="Gizmo axis"><span>Axis</span>{#each ['all','x','y','z'] as value}<button class="compact-button" class:active={axis===value} aria-pressed={axis===value} aria-disabled={busy||value!=='all'&&!(tool==='translate'&&canMove)&&(!node||!editable(node,'xyz'.indexOf(value)))} use:tooltip={value==='all'?'Show all available axes.':!(tool==='translate'&&canMove)&&node&&!editable(node,'xyz'.indexOf(value))?value.toUpperCase()+' is locked or driven by another DAZ channel.':'Show only '+value.toUpperCase()+' for easier, precise dragging.'} onclick={()=>{if(!busy&&(value==='all'||tool==='translate'&&canMove||node&&editable(node,'xyz'.indexOf(value))))axis=value as EditAxis;}}>{value==='all'?'All':value.toUpperCase()}</button>{/each}</div>
      {#if tool==='rotate'&&axis!=='all'}<button class="face-axis text-button" disabled={busy||selectedBone===figureKey} use:tooltip={'Align and zoom the camera to face the '+axis.toUpperCase()+' rotation ring. This changes only the view; Fit restores the whole interaction.'} onclick={onFocus}><Crosshair size={12}/> Face {axis.toUpperCase()} rotation ring</button>{/if}
      <label class="editor-check" use:tooltip={'Show clickable joint handles through the selected mannequin. Handles remain the same screen size when you zoom.'}><input type="checkbox" bind:checked={handles}/> Show joint handles</label>
      {#if group}<label class="editor-check" use:tooltip={'Fade other participants so their surfaces do not obscure the selected mannequin. Disable to inspect contact. This changes only the preview.'}><input type="checkbox" bind:checked={ghostPartners}/> Ghost other mannequins</label>{/if}
      <FigureSetup {pose} baseline={baseline??pose} height={floorHeight} {group} bind:linked {busy} {onFacing} onHeight={onFloorOffset} {onEditing}/>
      <section class="joint-pinning" aria-label="Joint pinning">
        <h3><Pin size={13}/> Joint pins <small>{pinStatus.length?pinStatus.length+' pinned':'World space'}</small></h3>
        <div class="pin-actions">{#each ['position','rotation'] as component}<button class="secondary" class:active={!!selectedPin?.[component as 'position'|'rotation']} aria-pressed={!!selectedPin?.[component as 'position'|'rotation']} disabled={busy||!canPin} aria-label={(selectedPin?.[component as 'position'|'rotation']?'Unpin ':'Pin ')+component} onclick={()=>onPin(component as 'position'|'rotation')} use:tooltip={!canPin?'Choose a joint to pin. Whole figure remains available for placement.':component==='position'?'Hold this joint centre in world space while editing parents. Unpin before moving it directly.':'Hold this joint’s world orientation while editing parents. Unpin before rotating it directly.'}>{#if selectedPin?.[component as 'position'|'rotation']}<Pin size={12}/>{/if}{component==='position'?'Position':'Rotation'}</button>{/each}</div>
        {#if pinStatus.length}<details class="pinned-list"><summary use:tooltip={'Inspect pin distance and rotation error, or select a pinned joint.'}>Pinned joints <ChevronDown size={12}/></summary><div>{#each pinStatus as state}<button class="pin-entry" class:strained={(state.distanceCm??0)>.5||(state.angleDegrees??0)>2} onclick={()=>onSelect(state.bone)} disabled={busy} use:tooltip={'Select this pin. Joint limits and reach can prevent exact placement; errors remain visible.'}><span>{jointLabel(pose!.rig.nodes.find(n=>n.id===state.bone)!)}</span><small>{state.distanceCm!==null?state.distanceCm.toFixed(2)+' cm':''}{state.distanceCm!==null&&state.angleDegrees!==null?' · ':''}{state.angleDegrees!==null?state.angleDegrees.toFixed(1)+'°':''}</small></button>{/each}</div></details><button class="text-button" disabled={busy} onclick={onUnpinAll} use:tooltip={'Remove all pins from this mannequin. Pose channels stay intact. Undo restores the pins.'}><PinOff size={12}/> Unpin all</button>{/if}
