      <div class="joint-groups" aria-label="Body part groups">{#each ['body','arms','legs','hands'] as value}<button class:active={jointGroup===value} aria-pressed={jointGroup===value} disabled={busy} use:tooltip={'Choose '+value+' joints. The surface and export rig stay unchanged.'} onclick={()=>{jointGroup=value as JointGroup;if(value==='hands'){const hand=pose!.rig.nodes.find(n=>new RegExp('^'+handSide+'_?hand$','i').test(n.id));if(hand){onSelect(hand.id);tool='select';onFocus();}}}}>{value[0].toUpperCase()+value.slice(1)}</button>{/each}</div>
      {#if jointGroup==='hands'}<div class="hand-side">{#each ['l','r'] as side}<button class="compact-button" class:active={handSide===side} aria-pressed={handSide===side} disabled={busy} use:tooltip={'Show '+(side==='l'?'left':'right')+' hand and finger joints.'} onclick={()=>{handSide=side;const hand=pose!.rig.nodes.find(n=>new RegExp('^'+side+'_?hand$','i').test(n.id));if(hand){onSelect(hand.id);tool='select';onFocus();}}}>{side==='l'?'Left hand':'Right hand'}</button>{/each}</div>{/if}
      {#if selectorStyle==='map'}<BodyMap {pose} selected={selectedBone} group={jointGroup} side={handSide} {busy} {onSelect}/>{:else}<div class="quick-joints" class:fingers={jointGroup==='hands'}>{#each quick as n}<button class:active={n.id===selectedBone} aria-pressed={n.id===selectedBone} disabled={busy} use:tooltip={'Select '+jointLabel(n)+'. '+(isReachJoint(n.id)?'Move fits its parent limb; Rotate edits this joint.':'Rotate edits its existing DAZ channels.')} onclick={()=>onSelect(n.id)}>{jointGroup==='hands'?jointLabel(n).replace(/^(Left|Right) /,''):jointLabel(n)}</button>{/each}</div>{/if}
      <button class="whole-figure-button" class:active={selectedBone===figureKey} aria-pressed={selectedBone===figureKey} disabled={busy} onclick={()=>onSelect(figureKey)} use:tooltip={'Select the whole figure to edit placement and orientation without changing its joint pose.'}><Move size={13}/> Whole figure</button>
      <details class="editor-advanced joint-search"><summary use:tooltip={'Browse joints by body region or search names, including twist and finger joints.'}>Find any joint <ChevronDown size={13}/></summary>
        <div class="editor-advanced-body">
          <div class="joint-search-field"><Search size={13} aria-hidden="true"/><input id="joint-search" aria-label="Find a joint" placeholder="Try left hand or shoulder…" bind:value={search} use:tooltip={'Search joint names and body regions. Try left finger, elbow or foot.'}/>{#if search}<button class="icon-button" aria-label="Clear joint search" onclick={()=>search=''} use:tooltip={'Clear the search; keep the selected joint.'}><X size={12}/></button>{/if}</div>
          <div class="joint-search-filters" role="group" aria-label="Filter joint search">{#each jointFilters as filter}<button class:active={searchGroup===filter.id} aria-pressed={searchGroup===filter.id} disabled={busy} onclick={()=>searchGroup=filter.id} use:tooltip={'Browse '+(filter.id==='all'?'every editable joint':filter.label.toLowerCase()+' joints')+'. Your current selection stays intact.'}>{filter.label}</button>{/each}</div>
          <p class="joint-search-count" role="status">{searchCount} {searchCount===1?'joint':'joints'}{search.trim()?' matching “'+search.trim()+'”':''}</p>
          <div class="joint-search-results" aria-label="Grouped joint results">
            {#each searchGroups as section (section.id)}<details class="joint-result-group" open={!!search.trim()||searchGroup!=='all'}><summary use:tooltip={'Browse '+section.label.toLowerCase()+'. Selection keeps this section open.'}><span>{section.label}</span><small>{section.nodes.length}</small><ChevronDown size={12}/></summary><div>{#each section.nodes as joint (joint.id)}<button class:active={selectedBone===joint.id} aria-pressed={selectedBone===joint.id} disabled={busy} onclick={()=>onSelect(joint.id)} use:tooltip={'Select '+jointLabel(joint)+'. Edits use its existing DAZ channels.'}>{jointLabel(joint).replace(/^(Left|Right) /,'')}</button>{/each}</div></details>{/each}
            {#if !searchCount}<p class="joint-search-empty">No matching joints. Try “hand”, or choose All.</p>{/if}
          </div>
        </div>
      </details>
      </details>
      {#if selectedBone===figureKey}<section class="editor-section"><h3>Figure position <small>cm</small></h3><div class="axis-fields">{#each ['X','Y','Z'] as axis,i}<label class={'axis-'+axis.toLowerCase()}>{axis}<input type="number" step="0.5" aria-label={'Figure position '+axis+' in cm'} disabled={busy} use:liveNumber={{value:pose.translation[i],context:pose.imageId+'/'+pose.personId+'/position/'+i,onValue:value=>positionAxis(i,value),onEditing}} use:tooltip={axis==='Z'?'Depth position in centimetres. Use Side view to correct spacing between partners.':axis==='Y'?'Vertical position in centimetres. Use Facing & floor above to adjust clearance from the floor.':'Horizontal position in centimetres.'}/></label>{/each}</div>
        <div class="depth-nudges"><span>Depth</span>{#each [-5,-1,1,5] as delta}<button class="compact-button" disabled={busy} use:tooltip={'Move '+(linked?'all participants':'this mannequin')+' '+delta+' cm along the scene Z axis.'} onclick={()=>positionAxis(2,pose!.translation[2]+delta)}>{delta>0?'+':''}{delta}</button>{/each}</div>
      </section>{/if}
      <section class="editor-section"><h3>{selectedBone===figureKey?'Figure orientation':'Joint rotation'} <small>degrees</small></h3><div class="axis-fields">{#each ['X','Y','Z'] as axis,i}<label class={'axis-'+axis.toLowerCase()}>{axis}<input type="number" step="1" aria-label={'Rotation '+axis+' in degrees'} disabled={busy||!!selectedPin?.rotation||!node||!editable(node,i)} min={node?.limits[axis.toLowerCase()]?.clamped?node.limits[axis.toLowerCase()].min:undefined} max={node?.limits[axis.toLowerCase()]?.clamped?node.limits[axis.toLowerCase()].max:undefined} use:liveNumber={{value:angles[i],context:pose.imageId+'/'+pose.personId+'/'+pose.rigId+'/'+selectedBone+'/'+i,normalize:value=>node?limited(node,i,value,angles[i]):angles[i],onValue:value=>rotationAxis(i,value),onEditing}} use:tooltip={selectedPin?.rotation?'Unpin Rotation to edit this joint’s orientation.':!node?'Choose a joint.':node.driven?.includes(axis.toLowerCase())?'Driven by another DAZ channel. Edit its controlling joint; this value is read-only.':node.limits[axis.toLowerCase()]?.locked?'This DAZ rotation axis is locked.':node.limits[axis.toLowerCase()]?.clamped?axis+' local rotation; limited to '+node.limits[axis.toLowerCase()].min+'°–'+node.limits[axis.toLowerCase()].max+'°.':axis+' local DAZ rotation in degrees.'}/></label>{/each}</div><p class="editor-caption">Live DAZ channels · {node?.order??'XYZ'} order · Rig limits stay active</p></section>
      <section class="editor-zero" aria-label="Zero pose"><h3><RotateCcw size={13}/> Zero pose</h3><div class="zero-actions"><button class="secondary" aria-label="Zero selected joint only" aria-disabled={busy||!canZeroSelected} use:tooltip={!canZeroSelected?'Already at zero, or remaining rotations are locked, driven or at a rig limit.':selectedBone===figureKey?'Set this figure’s orientation to 0°. Keep its pose and scene position. One Undo restores it.':'Set only this joint’s editable local rotations to 0°. Children keep their own rotation values; DAZ drivers still apply. One Undo restores it.'} onclick={()=>{if(!busy&&canZeroSelected)onZero(false);}}>Selected only</button><button class="secondary" aria-label="Zero selected joint and children" aria-disabled={busy||!canZeroChildren} use:tooltip={!canZeroChildren?'This joint and its children are already at zero, or remaining rotations are locked, driven or at a rig limit.':selectedBone===figureKey?'Zero this mannequin’s orientation and all bone rotations. Keep scene position and other mannequins. One Undo restores the complete pose.':'Zero this joint and every descendant joint, including fingers or toes. Keep the parent joints and other mannequins. One Undo restores the whole operation.'} onclick={()=>{if(!busy&&canZeroChildren)onZero(true);}}>With children</button></div><p class="editor-caption">0° rotations · Position kept · Affected pins cleared</p></section>
      <details class="editor-advanced"><summary use:tooltip={'Small rotation steps, gizmo space, snapping, and local draft options.'}>Precision & advanced <ChevronDown size={13}/></summary><div class="editor-advanced-body"><div class="rotation-nudges">{#each ['X','Y','Z'] as name,i}<div><span class={'axis-'+name.toLowerCase()}>{name}</span>{#each [-5,-1,1,5] as delta}<button class="compact-button" disabled={busy||!!selectedPin?.rotation||!node||!editable(node,i)} use:tooltip={'Adjust '+name+' local rotation by '+delta+'°. Existing limits remain active.'} onclick={()=>rotationAxis(i,limited(node!,i,angles[i]+delta,angles[i]))}>{delta>0?'+':''}{delta}°</button>{/each}</div>{/each}</div><label for="gizmo-space">Rotation gizmo space</label><select id="gizmo-space" bind:value={space} use:tooltip={'World aligns rotation rings with the scene; Local aligns them with the joint. Movement arrows always use world axes. Numeric rotation values remain local DAZ channels.'}><option value="local">Local joint axes</option><option value="world">World axes</option></select><label class="editor-check" use:tooltip={'Snap translation to 1 cm and rotation to 5°. Numeric fields remain precise.'}><input type="checkbox" bind:checked={snap}/> Snap gizmo movement</label><div class="draft-actions"><button class="secondary" disabled={busy||!canDraft} onclick={onSave} use:tooltip={canDraft?'Save this editor pose locally in History → Pose edits.':'Drafts require the desktop app and an open pose.'}><Save size={13}/> Save draft</button><button class="secondary" disabled={busy||!canDraft} onclick={onLoad} use:tooltip={canDraft?'Restore this saved editor draft. Actual rig or person metadata changes are rejected.':'Drafts are available in the desktop app.'}><FolderOpen size={13}/> Restore</button></div></div></details>
