      <div class="editor-resets"><button class="text-button" disabled={busy} onclick={()=>onReset(false)} use:tooltip={reachJoint?'Restore this hand or foot and its parent limb to the pose when editing began. Undo restores your changes.':'Restore the selected joint or figure to its pose when editing began. Clear affected pins; Undo restores both.'}><RotateCcw size={13}/> Reset selected</button><button class="text-button" disabled={busy} onclick={()=>onReset(true)} use:tooltip={'Restore every participant to the pose captured when editing began. This is undoable.'}>Reset all edits</button></div>
    {/if}
  </div>{/if}
</div>
<style>
  .joint-pinning{padding:10px;border:1px solid var(--line);border-radius:8px;background:var(--deep)}
  .joint-pinning h3{display:flex;align-items:center;gap:6px;font-size:11px;margin:0 0 8px}
  .joint-pinning h3 small{margin-left:auto;font-size:9px;font-weight:400;color:var(--muted)}
  .pin-actions{display:grid;grid-template-columns:1fr 1fr;gap:6px}
  .pin-actions button{font-size:10px;justify-content:center;padding:8px 4px}
  .pin-actions button.active{color:var(--accent);background:var(--tint);border-color:var(--accent)}
  .joint-pinning .editor-caption{margin:7px 0 0;font-size:9px;line-height:1.5}
  .pinned-list summary{display:flex;align-items:center;justify-content:space-between;cursor:pointer;font-size:10px;list-style:none;padding:10px 0 6px}
  .pinned-list summary::-webkit-details-marker{display:none}
  .pinned-list>div{display:grid;gap:3px;max-height:140px;overflow:auto}
  .pin-entry{display:flex;justify-content:space-between;gap:6px;font-size:10px;padding:7px 5px;border:1px solid var(--line);border-radius:5px;background:var(--surface);color:var(--text);text-align:left}
  .pin-entry small{font-size:9px;color:var(--muted);white-space:nowrap}
  .pin-entry.strained small{color:var(--warning,var(--accent))}

  .editor-zero{border:1px solid var(--line);border-radius:8px;padding:10px;background:var(--deep)}
  .editor-zero h3{display:flex;align-items:center;gap:6px;font-size:11px;margin:0 0 9px}
  .zero-actions{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px}
  .zero-actions button{justify-content:center;font-size:10px;padding:8px 4px;min-width:0}
  .editor-zero .editor-caption{margin:8px 0 0;font-size:9px;line-height:1.5}

  .joint-search-field{display:flex;align-items:center;gap:7px;border:1px solid var(--line);border-radius:7px;background:var(--deep);padding-left:9px;color:var(--muted)}
  .joint-search .joint-search-field input{flex:1;min-width:0;width:100%;margin:0;padding:8px 0;background:transparent;border:0;outline:none;font-size:11px}
